//===- mac_mode.cc ----------------------------------------------*- C++ -*-===//
//
// rand capture kernel for MAC config mode (0, 2, 1) `4x4_4x4_2ch`
// (GENERATED by tools/gen_mac_modes.py). Per tile and signedness flavour (ss, su, us,
// uu; first letter is A) it runs mul_4x4_4x4_2ch, then mac and msc chained on the result.
// Chunk layout: 6 operand blocks of T tiles (A0 B0 A1 B1 A2 B2).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

#include <aie_api/aie.hpp>

#define T 16
#define OUT_WORDS_PER_TILE 384

#define STORE(r, dst) \
  do { aie::accum<acc32, 32> w(r); aie::store_v((dst), w.to_vector<int32>(0)); } while (0)

extern "C" {

void mac_mode(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 64;
  uint8_t *in2 = in + 0 + T * 64 + T * 64;
  uint8_t *in3 = in + 0 + T * 64 + T * 64 + T * 64;
  uint8_t *in4 = in + 0 + T * 64 + T * 64 + T * 64 + T * 64;
  uint8_t *in5 = in + 0 + T * 64 + T * 64 + T * 64 + T * 64 + T * 64;
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // ss
      v32int16 v0 = *(v32int16 *)(in0 + n * 64);
      v64int8 v1 = *(v64int8 *)(in1 + n * 64);
      v32int16 v2 = *(v32int16 *)(in2 + n * 64);
      v64int8 v3 = *(v64int8 *)(in3 + n * 64);
      v32int16 v4 = *(v32int16 *)(in4 + n * 64);
      v64int8 v5 = *(v64int8 *)(in5 + n * 64);
      v32acc32 r0 = mul_4x4_4x4_2ch(v0, v1);
      v32acc32 r1 = mac_4x4_4x4_2ch(v2, v3, r0);
      v32acc32 r2 = msc_4x4_4x4_2ch(v4, v5, r1);
      STORE(r0, o + 0);
      STORE(r1, o + 32);
      STORE(r2, o + 64);
    }
    { // su
      v32int16 v0 = *(v32int16 *)(in0 + n * 64);
      v64uint8 v1 = *(v64uint8 *)(in1 + n * 64);
      v32int16 v2 = *(v32int16 *)(in2 + n * 64);
      v64uint8 v3 = *(v64uint8 *)(in3 + n * 64);
      v32int16 v4 = *(v32int16 *)(in4 + n * 64);
      v64uint8 v5 = *(v64uint8 *)(in5 + n * 64);
      v32acc32 r0 = mul_4x4_4x4_2ch(v0, v1);
      v32acc32 r1 = mac_4x4_4x4_2ch(v2, v3, r0);
      v32acc32 r2 = msc_4x4_4x4_2ch(v4, v5, r1);
      STORE(r0, o + 96);
      STORE(r1, o + 128);
      STORE(r2, o + 160);
    }
    { // us
      v32uint16 v0 = *(v32uint16 *)(in0 + n * 64);
      v64int8 v1 = *(v64int8 *)(in1 + n * 64);
      v32uint16 v2 = *(v32uint16 *)(in2 + n * 64);
      v64int8 v3 = *(v64int8 *)(in3 + n * 64);
      v32uint16 v4 = *(v32uint16 *)(in4 + n * 64);
      v64int8 v5 = *(v64int8 *)(in5 + n * 64);
      v32acc32 r0 = mul_4x4_4x4_2ch(v0, v1);
      v32acc32 r1 = mac_4x4_4x4_2ch(v2, v3, r0);
      v32acc32 r2 = msc_4x4_4x4_2ch(v4, v5, r1);
      STORE(r0, o + 192);
      STORE(r1, o + 224);
      STORE(r2, o + 256);
    }
    { // uu
      v32uint16 v0 = *(v32uint16 *)(in0 + n * 64);
      v64uint8 v1 = *(v64uint8 *)(in1 + n * 64);
      v32uint16 v2 = *(v32uint16 *)(in2 + n * 64);
      v64uint8 v3 = *(v64uint8 *)(in3 + n * 64);
      v32uint16 v4 = *(v32uint16 *)(in4 + n * 64);
      v64uint8 v5 = *(v64uint8 *)(in5 + n * 64);
      v32acc32 r0 = mul_4x4_4x4_2ch(v0, v1);
      v32acc32 r1 = mac_4x4_4x4_2ch(v2, v3, r0);
      v32acc32 r2 = msc_4x4_4x4_2ch(v4, v5, r1);
      STORE(r0, o + 288);
      STORE(r1, o + 320);
      STORE(r2, o + 352);
    }
  }
  event1();
}

} // extern "C"
